-- Tabelas da Agenda como usadas pelo código original (tipos deduzidos: texto para data/hora,
-- 'Sim'/'Não' para as equipes de apoio). Inclui dados com casos reais: horário antigo em texto,
-- evento passado, ficha trancada, série recorrente (lote) e coordenadores com senha em texto.
create table public.eventos (id bigint generated by default as identity primary key, titulo text, data text, ministerio text, lider text,
  horario text, horario_inicio text, horario_fim text, local text, necessita_midia text, necessita_louvor text, necessita_diaconia text,
  midia_tema text, midia_arte text, midia_banner text, midia_inscricao text, midia_link_inscricao text, midia_info text, observacoes text,
  link_fotos text, link_videos text, bloqueado boolean default false, atualizado_em timestamptz);
create table public.reservas (id bigint generated by default as identity primary key, ministerio text, motivo text, espacos text, data text,
  horario_inicio text, horario_fim text, lote_id text);
create table public.coordenadores (id bigint generated by default as identity primary key, nome text, login text unique, senha text not null, ativo boolean default true);
-- Como o projeto atual funciona hoje: RLS desligado e a chave pública com acesso total
grant all on public.eventos, public.reservas, public.coordenadores to anon, authenticated;

